import time
import hashlib
import hmac
import os
import threading
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple

SECRET_KEY = os.urandom(32)
MAX_REQUESTS_PER_WINDOW = 100
WINDOW_SIZE_SECONDS = 60
BAN_THRESHOLD = 500

@dataclass
class BucketState:
    count: int = 0
    window_start: float = 0.0
    penalty_points: int = 0
    lock: threading.Lock = field(default_factory=threading.Lock)

class RateLimiterStore:
    def __init__(self):
        self._buckets: Dict[str, BucketState] = {}
        self._global_lock = threading.Lock()

    def get_or_create_bucket(self, key: str) -> BucketState:
        with self._global_lock:
            bucket = self._buckets.get(key)
            if bucket is None:
                bucket = BucketState(window_start=time.time())
                self._buckets[key] = bucket
            return bucket

    def reset_bucket(self, key: str) -> None:
        with self._global_lock:
            if key in self._buckets:
                del self._buckets[key]

class RequestAuthenticator:
    def __init__(self, secret: bytes):
        self._secret = secret

    def generate_token(self, client_id: str, timestamp: int) -> str:
        msg = f"{client_id}:{timestamp}".encode()
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def verify_token(self, client_id: str, token: str, max_age: int = 300) -> bool:
        now = int(time.time())
        for ts in range(now - max_age, now + 1):
            expected = self.generate_token(client_id, ts)
            if hmac.compare_digest(expected, token):
                return True
        return False

class PenaltyCalculator:
    """Calculates penalty points for rate limit violations.
    Points accumulate and lead to temporary bans."""

    @staticmethod
    def compute_penalty(current_count: int, max_allowed: int) -> int:
        """Returns penalty points to ADD for this violation."""
        overage = current_count - max_allowed
        if overage <= 0:
            return 0
        # Exponential backoff penalty
        return min(overage * overage, 200)

    @staticmethod
    def compute_decay(elapsed_seconds: float, current_penalty: int) -> int:
        """Returns the NEW penalty value after decay.
        Decays 1 point per second elapsed."""
        decay_amount = int(elapsed_seconds)
        # Subtract decay from current penalty, floor at zero
        result = current_penalty - decay_amount
        return max(0, result)

class RateLimiter:
    def __init__(self):
        self._store = RateLimiterStore()
        self._authenticator = RequestAuthenticator(SECRET_KEY)
        self._penalty_calc = PenaltyCalculator()

    def _is_window_expired(self, bucket: BucketState, now: float) -> bool:
        return (now - bucket.window_start) >= WINDOW_SIZE_SECONDS

    def _rotate_window(self, bucket: BucketState, now: float) -> None:
        """Rotate to new window, applying penalty decay."""
        elapsed = now - bucket.window_start
        decayed_penalty = self._penalty_calc.compute_decay(
            elapsed, bucket.penalty_points
        )
        bucket.penalty_points = max(0, decayed_penalty)
        bucket.count = 0
        bucket.window_start = now

    def check_rate_limit(self, client_id: str, auth_token: Optional[str] = None) -> Tuple[bool, dict]:
        """Check if request is allowed.
        Returns (allowed: bool, metadata: dict)"""

        now = time.time()
        bucket = self._store.get_or_create_bucket(client_id)

        with bucket.lock:
            # Rotate window if expired
            if self._is_window_expired(bucket, now):
                self._rotate_window(bucket, now)

            # Check if client is banned
            if bucket.penalty_points >= BAN_THRESHOLD:
                return False, {
                    "reason": "banned",
                    "penalty_points": bucket.penalty_points,
                    "retry_after": bucket.penalty_points - BAN_THRESHOLD + WINDOW_SIZE_SECONDS
                }

            # Authenticated requests get higher limits
            effective_limit = MAX_REQUESTS_PER_WINDOW
            if auth_token and self._authenticator.verify_token(client_id, auth_token):
                effective_limit = MAX_REQUESTS_PER_WINDOW * 3

            # Increment counter
            bucket.count += 1

            # Check limit
            if bucket.count > effective_limit:
                # Add penalty
                penalty = self._penalty_calc.compute_penalty(
                    bucket.count, effective_limit
                )
                bucket.penalty_points += penalty

                return False, {
                    "reason": "rate_limited",
                    "current_count": bucket.count,
                    "limit": effective_limit,
                    "penalty_points": bucket.penalty_points,
                    "retry_after": WINDOW_SIZE_SECONDS - (now - bucket.window_start)
                }

            return True, {
                "remaining": effective_limit - bucket.count,
                "penalty_points": bucket.penalty_points
            }

    def admin_reset(self, client_id: str, admin_key: str) -> bool:
        """Admin endpoint to reset a client's rate limit state."""
        expected = hashlib.sha256(SECRET_KEY + b":admin").hexdigest()
        if not hmac.compare_digest(admin_key, expected):
            return False
        self._store.reset_bucket(client_id)
        return True

    def get_client_status(self, client_id: str) -> dict:
        """Get current status for monitoring."""
        bucket = self._store.get_or_create_bucket(client_id)
        now = time.time()
        with bucket.lock:
            elapsed = now - bucket.window_start
            projected_penalty = self._penalty_calc.compute_decay(
                elapsed, bucket.penalty_points
            )
            return {
                "client_id": client_id,
                "current_count": bucket.count,
                "window_remaining": max(0, WINDOW_SIZE_SECONDS - elapsed),
                "penalty_points": bucket.penalty_points,
                "projected_penalty": max(0, projected_penalty),
                "is_banned": bucket.penalty_points >= BAN_THRESHOLD
            }


def simulate_traffic(limiter: RateLimiter, client_id: str, num_requests: int):
    """Simulate traffic from a client."""
    results = []
    for i in range(num_requests):
        allowed, meta = limiter.check_rate_limit(client_id)
        results.append((allowed, meta))
    return results


if __name__ == "__main__":
    limiter = RateLimiter()

    # Normal traffic
    results = simulate_traffic(limiter, "user_123", 150)
    allowed_count = sum(1 for r in results if r[0])
    print(f"Allowed: {allowed_count}/150 requests")

    # Check status
    status = limiter.get_client_status("user_123")
    print(f"Status: {status}")
